let activeModalTemplateKey = null;

function renderTemplatesGrid() {
  const grid = document.getElementById('templatesGrid');
  grid.innerHTML = Object.keys(baseTemplates).map(key => {
    const meta = templateMeta[key];
    return `
      <div class="template-card">
        <div class="preview-container">
          <div class="watermark"><div class="watermark-text">ULTRAEDGEAI WATERMARKED</div></div>
          <iframe srcdoc="${escapeHtml(baseTemplates[key])}" title="${meta.title}" sandbox="allow-scripts allow-same-origin"></iframe>
        </div>
        <div class="card-body">
          <div class="card-title">
            <span>${meta.title}</span>
            <span class="badge">${meta.badge}</span>
          </div>
          <div class="amenities-list">
            ${meta.amenities.map(a => `<span class="amenity-chip">${a}</span>`).join('')}
          </div>
          <div class="card-actions">
            <button class="btn btn-secondary" onclick="openFullscreenModal('${key}')">👁️ Preview</button>
            <button class="btn" onclick="downloadTemplate('${key}')">⬇️ Download</button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function escapeHtml(str) {
  return str.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

function openFullscreenModal(key) {
  activeModalTemplateKey = key;
  document.getElementById('modalTemplateTitle').innerText = templateMeta[key].title + " - Full Preview";
  document.getElementById('fullscreenIframe').srcdoc = baseTemplates[key];
  document.getElementById('fullscreenModal').style.display = 'flex';
}

function closeFullscreenModal() {
  document.getElementById('fullscreenModal').style.display = 'none';
  document.getElementById('fullscreenIframe').srcdoc = '';
}

function downloadTemplate(key) {
  // Remove injected internal link handling script on export
  let rawCode = baseTemplates[key].replace(iframeLinkScript, '');
  const blob = new Blob([rawCode], { type: 'text/html' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${key}-template.html`;
  a.click();
  URL.revokeObjectURL(a.href);
}

function downloadModalTemplate() {
  if (activeModalTemplateKey) downloadTemplate(activeModalTemplateKey);
}

/* Modal Handlers */
function openPrivacyModal() { document.getElementById('privacyModal').style.display = 'flex'; }
function closePrivacyModal() { document.getElementById('privacyModal').style.display = 'none'; }

function openDocsModal() { document.getElementById('docsModal').style.display = 'flex'; }
function closeDocsModal() { document.getElementById('docsModal').style.display = 'none'; }

function openDonateModal() { document.getElementById('donateModal').style.display = 'flex'; }
function closeDonateModal() { document.getElementById('donateModal').style.display = 'none'; }

renderTemplatesGrid();